package com.example.application_service.controller;import com.example.application_service.common.ApiResponse;import com.example.application_service.dto.ApplicationDtos;import com.example.application_service.exception.*;import com.example.application_service.security.RequestIdentity;import com.example.application_service.service.ApplicationService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/applications") public class ApplicationController{private final ApplicationService applications;public ApplicationController(ApplicationService a){applications=a;}@PostMapping public ResponseEntity<ApiResponse<ApplicationDtos.View>> apply(@Valid @RequestBody ApplicationDtos.Apply body,RequestIdentity identity,HttpServletRequest request){role(identity,"CANDIDATE");return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok("Application submitted",applications.apply(body,identity.userId(),identity.email(),trace(request))));}@GetMapping("/me")public ApiResponse<ApplicationDtos.PageData<ApplicationDtos.View>> mine(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="newest")String sort,RequestIdentity identity){role(identity,"CANDIDATE");return ApiResponse.ok("Applications retrieved",applications.candidateList(identity.userId(),page,size,sort));}@GetMapping("/{id}")public ApiResponse<ApplicationDtos.Detail> detail(@PathVariable UUID id,RequestIdentity identity,HttpServletRequest request){return ApiResponse.ok("Application retrieved",applications.detail(id,identity.userId(),identity.role(),trace(request)));}@PatchMapping("/{id}/status")public ApiResponse<ApplicationDtos.Detail> status(@PathVariable UUID id,@Valid @RequestBody ApplicationDtos.StatusChange body,RequestIdentity identity,HttpServletRequest request){role(identity,"EMPLOYER");return ApiResponse.ok("Application status updated",applications.changeStatus(id,body,identity.userId(),trace(request)));}private void role(RequestIdentity i,String r){if(!r.equals(i.role()))throw new ApiException(HttpStatus.FORBIDDEN,"ACCESS_DENIED",r+" role is required");}private String trace(HttpServletRequest r){return String.valueOf(r.getAttribute(CorrelationIdFilter.ATTRIBUTE));}}
